//! The Haxe classes: one module per interface, generated once for HashLink
//! and once for hxcpp, with the same public API.
//!
//! Each object owns one handle. A value the library returns is adopted by a
//! new object of its interface's class, which is how a return value of
//! another interface, or of a function other than `new`, gets an owner.

use crate::data;
use crate::lent;
use crate::model::{Data, Interface, Library, Method, Number, Type};
use crate::names::{camel, exception_class, has_receiver, haxe_param, memory_class, thrown_class};

/// A generated file: its path relative to a class path, and its text.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct File {
    pub path: String,
    pub text: String,
}

pub(crate) const HEADER: &str = "// Generated by hxn-gen from the library's source. Do not edit.\n";

// Moves every file into the library's package, if it declares one: under
// the package's directory, with a `package` line after the header. The
// classes refer to each other by bare name, so nothing else changes.
pub(crate) fn in_package(library: &Library, files: Vec<File>) -> Vec<File> {
    let Some(package) = &library.package else {
        return files;
    };
    let dir = package.replace('.', "/");
    files
        .into_iter()
        .map(|file| {
            let body = file.text.strip_prefix(HEADER).unwrap_or(&file.text);
            File {
                path: format!("{dir}/{}", file.path),
                text: format!("{HEADER}package {package};\n\n{body}"),
            }
        })
        .collect()
}

pub(crate) fn haxe_type(ty: &Type) -> String {
    match ty {
        Type::Void => String::from("Void"),
        Type::Bool => String::from("Bool"),
        Type::I32 => String::from("Int"),
        Type::I64 => String::from("haxe.Int64"),
        Type::F64 => String::from("Float"),
        Type::Str => String::from("String"),
        Type::Bytes | Type::BytesMut => String::from("haxe.io.Bytes"),
        Type::Future(of) => format!("hxn.Future<{}>", carried_type(of)),
        Type::Stream(of) => format!("hxn.Stream<{}>", carried_type(of)),
        Type::Signal(of) => format!("hxn.Signal<{}>", haxe_type(of)),
        Type::Lent { params, returns } => lent::haxe_type(params, returns),
        Type::Data(data) => data::haxe_type(data),
        Type::Fallible { value, .. } => carried_type(value),
        Type::List { interface } => format!("Array<{interface}>"),
        Type::AtomicInt => String::from("hxn.AtomicInt"),
        Type::AtomicBool => String::from("hxn.AtomicBool"),
        Type::Handle {
            interface,
            nullable: false,
        } => interface.clone(),
        Type::Handle {
            interface,
            nullable: true,
        } => format!("Null<{interface}>"),
    }
}

// The Haxe type a future or stream carries, or `hxn.Unit` for `()`.
fn carried_type(carried: &Type) -> String {
    match carried {
        Type::Void => String::from("hxn.Unit"),
        other => haxe_type(other),
    }
}

pub(crate) fn docs(lines: &[String], indent: &str) -> String {
    match lines {
        [] => String::new(),
        [line] => format!("{indent}/** {line} **/\n"),
        lines => {
            let mut out = format!("{indent}/**\n");
            for line in lines {
                out.push_str(&format!("{indent}\t{line}\n"));
            }
            out.push_str(&format!("{indent}**/\n"));
            out
        }
    }
}

// A number uses the Haxe type of its wire type, except `u32`, which is a
// `UInt`.
fn number_type(number: Option<Number>, ty: &Type) -> String {
    match number {
        Some(Number::U32) => String::from("UInt"),
        _ => haxe_type(ty),
    }
}

fn params(method: &Method) -> String {
    let params: Vec<String> = method
        .params
        .iter()
        .map(|param| {
            let ty = match &param.data {
                Some(data) => data::haxe_type(data),
                None => number_type(param.number, &param.ty),
            };
            format!("{}:{ty}", haxe_param(&param.name))
        })
        .collect();
    params.join(", ")
}

// A data parameter passed as bytes: the statements that serialize it, and
// the variable holding the bytes.
pub(crate) fn written(name: &str, data: &Data) -> (Vec<String>, String) {
    let out = format!("{name}Out");
    let mut lines = vec![format!("var {out} = new haxe.io.BytesBuffer();")];
    lines.extend(data::haxe_write(data, name, &out, 0));
    let bytes = format!("{name}Bytes");
    lines.push(format!("var {bytes} = {out}.getBytes();"));
    (lines, bytes)
}

// The statements that deserialize a data return value from its bytes.
pub(crate) fn read(data: &Data, bytes: &str) -> Vec<String> {
    vec![
        format!("var input = new haxe.io.BytesInput({bytes});"),
        format!("return {};", data::haxe_read(data)),
    ]
}

// `public function add(amount:Int):Int`, or the constructor's.
pub(crate) fn signature(method: &Method) -> String {
    if method.constructor {
        return format!("\tpublic function new({})", params(method));
    }
    let modifier = if has_receiver(method) { "" } else { "static " };
    let returns = match (&method.returns_data, &method.returns) {
        (Some(data), _) => data::haxe_type(data),
        (None, Type::Stream(of)) if method.returns_list => format!("Array<{}>", haxe_type(of)),
        (None, returns) => number_type(method.returns_number, returns),
    };
    format!(
        "\tpublic {modifier}function {}({}):{returns}",
        camel(&method.name),
        params(method),
    )
}

const CLOSE_DOCS: &str = "\t/**\n\t\tReleases the native value now. The collector does it otherwise. Using\n\t\tthis object afterwards throws.\n\t**/\n";

const SHARED_CLOSE_DOCS: &str = "\t/**\n\t\tGives up this object's share of the value now. The collector does it\n\t\totherwise. The value lives while anything else holds a share. Using\n\t\tthis object afterwards throws.\n\t**/\n";

pub(crate) const SAME_DOCS: &str = "\t/**\n\t\tWhether `other` holds the value this does. Two objects can: each time\n\t\tthe library returns the value, a new object gets a share of it.\n\t**/\n";

pub(crate) const WEAK_DOCS: &str =
    "\t/** A reference to the value that does not keep it alive. **/\n";

pub(crate) const UPGRADE_DOCS: &str =
    "\t/** The value, if anything still holds it: a new object with a share of its own. **/\n";

// The end of a class: its `close()`, which releases the value through
// `drop`, unless the library has a `close` of its own. Its object is then
// released only by the collector.
pub(crate) fn close(interface: &Interface, drop: &str) -> String {
    if own_close(interface) {
        return String::from("}\n");
    }
    format!(
        "\n{}\tpublic function close():Void\n\t\t{drop}(hxnRaw);\n}}\n",
        close_docs(interface)
    )
}

// Whether the library gives the interface a `close` of its own.
fn own_close(interface: &Interface) -> bool {
    interface
        .methods
        .iter()
        .any(|method| method.name == "close")
}

fn close_docs(interface: &Interface) -> &'static str {
    if interface.shared {
        SHARED_CLOSE_DOCS
    } else {
        CLOSE_DOCS
    }
}

// The library's memory meter, referenced by every class so that it exists
// whichever class a program uses.
pub(crate) fn meter(library: &Library) -> String {
    format!(
        "\t@:noCompletion static final hxnMemory = {}.meter;\n",
        memory_class(library)
    )
}

// The class whose `typed` builds the typed exception for a failure of
// `method`, if its error type is one of the library's data types. An async
// function's error rejects its future instead, which builds its own.
pub(crate) fn thrown(library: &Library, method: &Method) -> Option<String> {
    (method.error.is_some() && !method.asynchronous).then(|| thrown_class(library))
}

// A method's body from its statements. A method that passes callbacks makes
// its native call inside `hxn.Callback.during`, which rethrows a callback's
// exception once the library has returned. A method whose error type is one
// of the library's data types catches the thrown failure and throws the
// typed exception that `thrown` builds from it.
pub(crate) fn body(guards: &[String], lines: &[String], thrown: Option<&str>) -> String {
    let returns = lines.last().is_some_and(|line| line.starts_with("return "));
    let caught: Vec<String>;
    let lines = match thrown {
        Some(class) => {
            let mut all = vec![String::from("try {")];
            all.extend(
                lines
                    .iter()
                    .map(|line| format!("\t{}", line.replace('\n', "\n\t"))),
            );
            all.push(String::from("} catch (error:haxe.Exception) {"));
            all.push(format!("\tthrow {class}.typed(error);"));
            all.push(String::from("}"));
            caught = all;
            &caught[..]
        }
        None => lines,
    };
    let block = |lines: &[String]| {
        let mut out = String::from(" {\n");
        for line in lines {
            out.push_str(&format!("\t\t{line}\n"));
        }
        out.push_str("\t}\n");
        out
    };
    if guards.is_empty() {
        return match lines {
            [only] => format!("\n\t\t{only}\n"),
            lines => block(lines),
        };
    }
    let mut all = guards.to_vec();
    all.push(format!(
        "{}hxn.Callback.during(() -> {{",
        if returns { "return " } else { "" }
    ));
    for line in lines {
        all.push(format!("\t{}", line.replace('\n', "\n\t")));
    }
    if !returns {
        all.push(String::from("\treturn true;"));
    }
    all.push(String::from("});"));
    block(&all)
}

// A method of a weighed object first checks the library's memory, which an
// earlier call may have grown.
pub(crate) fn grown(interface: &Interface, method: &Method) -> Vec<String> {
    if interface.weighed && has_receiver(method) && !method.constructor {
        vec![String::from("hxnMemory.check();")]
    } else {
        Vec::new()
    }
}

// A class that only holds static functions and is never instantiated.
pub(crate) const NAMESPACE_DOCS: &str =
    "/** The library's functions that belong to no object. **/\n";

pub(crate) const THROWN_DOCS: &str = "Makes the exception a failure is thrown as, where the library failed with\n\tdata of its own: the value is asked for once the message has been caught.";

// Shared by both runtimes' classes: reads the error type's index, then the
// error.
pub(crate) fn thrown_read(library: &Library) -> String {
    let mut out = String::from(
        "\n\tstatic function read(error:haxe.Exception, input:haxe.io.BytesInput):haxe.Exception {\n\t\tswitch (input.readInt32()) {\n",
    );
    for (place, error) in library.errors().into_iter().enumerate() {
        out.push_str(&format!(
            "\t\t\tcase {place}:\n\t\t\t\tvar value:{} = {};\n\t\t\t\treturn new {}(error.message, value, error);\n",
            data::haxe_type(error),
            data::haxe_read(error),
            exception_class(&error.name())
        ));
    }
    out.push_str("\t\t\tcase _:\n\t\t\t\treturn error;\n\t\t}\n\t}\n}\n");
    out
}

pub(crate) const MEMORY_DOCS: &str = "What the library's values hold that the collector cannot see. A weighed\n\tobject checks it when it is made and before each of its methods runs, and\n\ta delivery does.";

// The extern class through which every hxcpp class of the library calls its
// glue. It also tells the build what to include and link.
// The hxcpp build settings of the library's native class: the header and
// library paths come through defines. Under Emscripten hxcpp links its own
// exception support but does not compile with it unless told to.
pub(crate) fn build_xml(library: &Library) -> String {
    let upper = library.name.to_uppercase();
    let name = &library.name;
    format!(
        "@:buildXml('\n<files id=\"haxe\">\n\t<compilerflag value=\"-I${{HXN_INCLUDE}}\"/>\n\t<compilerflag value=\"-I${{{upper}_INCLUDE}}\"/>\n\t<depend name=\"${{HXN_INCLUDE}}/hxn.h\"/>\n\t<depend name=\"${{{upper}_INCLUDE}}/{name}_abi.h\"/>\n\t<depend name=\"${{{upper}_INCLUDE}}/{name}_glue.h\"/>\n</files>\n<target id=\"haxe\">\n\t<lib name=\"${{{upper}_LIB}}\"/>\n\t<lib name=\"-lpthread\" if=\"linux\"/>\n\t<lib name=\"-ldl\" if=\"linux\"/>\n\t<lib name=\"kernel32.lib\" if=\"windows\"/>\n\t<lib name=\"ntdll.lib\" if=\"windows\"/>\n\t<lib name=\"userenv.lib\" if=\"windows\"/>\n\t<lib name=\"ws2_32.lib\" if=\"windows\"/>\n\t<lib name=\"dbghelp.lib\" if=\"windows\"/>\n</target>\n<!-- After the archive: a linker that reads libraries in order looks in them only for what is already undefined. -->\n<include name=\"${{{upper}_LINK}}\" if=\"{upper}_LINK\"/>\n')\n"
    )
}
